-- =====================================================================
-- 65 — Clients d'avant le site (27/11/2026)
--   115 anciens clients relevés dans Gmail (mails envoyés avant le lancement du site,
--   le 22/11/2026). Ils apparaissent dans l'admin > Clients avec l'étiquette « Avant le site ».
--   Catégories : A = lien de téléchargement seul, B = lien + clé, C = clé seule.
--   « paye » est une DÉDUCTION (aucune preuve de paiement dans les mails, tout passait par WhatsApp).
--   Aucun email n'est envoyé par ce fichier. Ces clients ne reçoivent rien automatiquement.
--   Pour tout retirer d'un coup : delete from public.legacy_customers;
-- À coller dans Supabase > SQL Editor > Run. Peut être relancé sans risque.
-- =====================================================================
create table if not exists public.legacy_customers (
  email           text primary key,
  name            text,
  category        text not null check (category in ('A','B','C','D')),
  category_label  text,
  product         text,
  device          text,
  activation      text,
  first_contact   date,
  last_contact    date,
  exchanges       int not null default 0,
  mails_sent      int not null default 0,
  client_replies  int not null default 0,
  links_sent      int not null default 0,
  keys_sent       int not null default 0,
  paid            text,
  phone           text,
  email_valid     text,
  notes           text,
  source          text not null default 'avant le site',
  imported_at     timestamptz not null default now()
);
alter table public.legacy_customers enable row level security;
revoke all on public.legacy_customers from anon, authenticated;
grant all on public.legacy_customers to service_role;

insert into public.legacy_customers (email, name, category, category_label, product, device, activation, first_contact, last_contact,
